"""Explain semaphore signal policies, trylock polarity and timeout results."""
import json
from rewrite_c_beginner import rewrite, ROOT
ROWS={'os1525': ('가위를 빌리러 왔는데 가위도 있고 중단 연락도 와 있다고 해 봅시다. 이 입구는 먼저 남은 가위를 확인합니다. 어떤 질문을 먼저 하느냐에 따라 결과가 달라질 수 있습니다.', '허가를 먼저 확인하는 경로와 신호 중단의 -EINTR을 구별합니다.', 'count=1·신호 있음 → 허가 소비·결과 0, count=0·허용 신호 있음 → 대기 항목 제거·-EINTR의 두 줄을 적으세요.', ['down_interruptible은 세마포어 허가를 얻되 허용된 신호로 기다림을 중단할 수 있는 함수입니다. 신호는 작업에 보내는 알림입니다. 함수는 성공 결과를 담을 result를 처음에 0으로 준비합니다.', '잠금을 잡고 count > 0인지 먼저 확인합니다. 허가가 있으면 count를 하나 줄이고 준비한 결과 0을 유지합니다. 예를 들어 count=1은 0이 되고 호출자는 허가 하나를 얻습니다. 이 빠른 경로에서는 느린 대기의 신호 검사를 거치지 않습니다.', '따라서 처리할 신호가 있어도 이미 허가가 준비되어 있으면 먼저 획득해 성공할 수 있습니다. interruptible이라는 이름은 모든 경로에서 신호를 가장 먼저 본다는 뜻이 아닙니다. 실제 분기 순서를 읽어야 합니다.', 'count=0이면 __down_interruptible을 통해 TASK_INTERRUPTIBLE 상태의 공통 대기에 들어갑니다. 대기 항목을 줄 끝에 넣고, 반복에서 신호와 시간 조건 등을 확인합니다. 실제 기다림은 raw 잠금을 풀고 실행 기회를 넘기는 구간에서 합니다.', '허용 신호로 중단되면 interrupted라는 이름표로 가서 대기 항목을 list_del로 제거하고 -EINTR을 반환합니다. 성공 0과 구별되는 음수 오류입니다. 앞서 completion이나 일반 waitqueue에서 본 -ERESTARTSYS와 이 함수의 오류 약속은 다릅니다.', '오류로 돌아왔다면 허가를 얻지 못한 것입니다. 획득한 것처럼 자원을 사용하거나 이 실패를 상쇄한다며 임의로 up을 부르면 안 됩니다. 성공과 실패를 먼저 구별한 뒤, 성공한 사용에 맞추어 정해진 반환 규칙을 지키세요.'], [('허가가 없어서 느린 대기로 갔다가 허용 신호로 중단됐어요. 결과는?', ['completion과 같으니 항상 -ERESTARTSYS예요', '이 세마포어 함수에서는 -EINTR이에요'], '공통 대기의 interrupted 경로는 항목을 제거하고 -EINTR을 반환합니다. 신호 중단이라는 의미가 비슷해도 API마다 오류 코드 약속은 다를 수 있어요.'), ('count=1이고 신호도 와 있어요. 항상 획득 실패일까요?', ['아니요. 먼저 허가를 확인해 소비하고 성공할 수 있어요', '네. 이 함수는 무조건 신호부터 확인해요'], '바깥 함수는 count > 0을 먼저 확인합니다. 신호 검사는 허가가 없어서 들어가는 느린 경로에 있어요. 따라서 이름만 보고 신호가 모든 경로에 우선한다고 외우면 안 됩니다.')]), 'os1526': ('“연락이 오면 중단”과 “긴급 종료 연락일 때 중단”은 서로 다른 약속입니다. 둘 다 중단되면 같은 오류 번호를 적더라도 허용한 연락 종류까지 같지는 않습니다.', 'killable의 대기 상태와 성공·중단 결과를 구별합니다.', 'interruptible → TASK_INTERRUPTIBLE, killable → TASK_KILLABLE을 적으세요. 둘 다 허가 성공 0, 허용 신호 중단 -EINTR이지만 신호 범위는 다르다고 표시하세요.', ['down_killable도 먼저 잠금을 잡고 남은 허가 count를 봅니다. 양수이면 하나 줄이고 0으로 성공합니다. 허가가 있으면 느린 경로에 들어가지 않으므로 기다리거나 그 안의 신호 검사를 수행할 필요가 없습니다.', '허가가 없으면 __down_killable이 공통 함수에 TASK_KILLABLE을 전달합니다. 이 상태는 치명적인 종료 신호에 반응할 수 있게 합니다. 일반 interruptible 변형은 TASK_INTERRUPTIBLE을 선택합니다.', '공통 함수는 signal_pending_state로 실제 신호와 대기 상태를 함께 검사합니다. 두 함수가 같은 -EINTR을 돌려줄 수 있다고 해서 모든 신호에 같은 방식으로 반응하는 것은 아닙니다. 결과 번호와 결과를 일으킨 조건을 나누어 보세요.', '허용된 신호로 중단되면 대기 항목을 제거하고 -EINTR을 돌려줍니다. 허가를 얻었으면 0입니다. 이 함수의 반환형은 int이며, 숫자 1을 성공이라고 정한 불리언 함수처럼 읽지 않습니다.', '__down, __down_interruptible, __down_killable, __down_timeout은 같은 공통 대기 알고리즘에 상태와 시간 인자를 달리 전달하는 작은 함수들입니다. 이런 함수를 wrapper, 즉 공통 동작을 감싼 입구라고 부릅니다. 각 입구가 실제로 무슨 인자를 넣는지 보면 차이를 찾을 수 있습니다.', '성공이면 허가를 가지고 다음 작업을 할 수 있고 실패면 획득하지 못한 것입니다. 실패 뒤 임의로 up을 해 허가를 늘리거나 획득을 가정해 자원을 만지지 마세요. 잠들 수 있는 상황에서 호출해야 한다는 조건도 상태 이름이 바뀌었다고 없어지지 않습니다.'], [('killable과 interruptible이 둘 다 -EINTR을 돌려줄 수 있으니 허용 신호도 같을까요?', ['네. 오류 번호가 같으면 모든 규칙이 같아요', '아니요. 선택한 상태와 중단을 허용하는 신호가 달라요'], 'TASK_KILLABLE과 TASK_INTERRUPTIBLE은 다른 상태입니다. 같은 결과 번호는 중단되었다는 공통 사실을 알릴 뿐, 어떤 신호로 중단할 수 있는지까지 같게 만들지 않습니다.'), ('down_killable이 허가를 얻었을 때 결과는?', ['0이에요', '언제나 1이에요'], '성공은 result의 초기값 0 또는 느린 경로의 성공 0입니다. 허가를 얻으면 참 1을 돌려주는 함수라고 추측하지 말고 이 함수의 약속을 따라 읽으세요.')]), 'os1527': ('대여 창구가 “빌렸으면 0, 못 빌렸으면 1”이라는 번호표를 준다고 해 봅시다. 다른 창구가 반대 약속을 쓴다고 이 창구의 0을 실패로 읽으면 안 됩니다.', 'trylock의 0 성공·1 실패와 서로 다른 count 자료형을 이해합니다.', 'count=2에서 임시 값 1 → 저장 1 → 결과 0을 적으세요. count=0이면 획득 실패 1이고 원래 count는 0으로 남는 경우와 비교하세요.', ['down_trylock은 완료될 때까지 잠들어 기다리지 않고 지금 허가를 얻을 수 있는지 시도합니다. 내부 raw 잠금을 잡기 위한 짧은 경쟁은 있을 수 있지만, 허가가 돌아올 때까지 대기 줄에 등록해 잠드는 경로는 없습니다.', '결과는 0이면 획득 성공, 1이면 획득 실패입니다. 원문은 spin_trylock과 mutex_trylock의 성공 방향과 반대라고 특별히 설명합니다. 함수 이름에 trylock이 있다는 이유로 반환값을 통일해 외우면 안 됩니다.', '잠금을 잡으면 count = sem->count - 1을 계산합니다. sem->count는 unsigned int 저장 칸이고 왼쪽 지역 변수 count는 int입니다. 지역 변수는 이 함수 안의 임시 칸입니다. 같은 count라는 이름이 보여도 두 칸과 두 자료형은 구별해야 합니다.', '정상적인 작은 허가 수 2를 예로 들면 임시 count는 1이 됩니다. count >= 0이므로 원래 sem->count에도 1을 저장합니다. 마지막 count < 0은 거짓이므로 C의 숫자 0을 반환합니다. 그래서 성공의 결과가 0입니다.', '허가 0인 경우에는 커널이 사용하는 변환 규칙에서 임시 값이 -1이 되어 저장을 건너뛰고 실패 1을 반환합니다. 다만 식의 뺄셈은 unsigned 자료가 포함된 계산이고 그 결과를 int에 넣는 단계가 있습니다. 모든 C 환경과 아주 큰 허가 값에서도 단순한 정수 뺄셈처럼 동작한다고 일반화하지 마세요.', '호출자는 유효한 초기 허가 수와 반환 횟수를 관리해야 합니다. 인터럽트 문맥에서도 사용 가능한 이 함수의 계약을 지키되, 반환 0을 확인한 뒤에만 획득한 자원을 사용합니다. if(result)일 때 성공 처리하면 이 함수에서는 의미가 뒤집힙니다.'], [('down_trylock이 0을 반환했어요. 무슨 뜻인가요?', ['허가 획득 실패예요', '허가 획득 성공이에요'], '이 함수는 성공 0, 실패 1입니다. 반환식 count < 0이 거짓이면 0이므로 유효한 허가를 소비한 길이 성공이 됩니다. 다른 trylock의 참·거짓 약속과 구별하세요.'), ('임시 지역 변수 count도 sem->count처럼 unsigned int인가요?', ['아니요. 지역 변수는 int로 선언돼 있어요', '네. 이름이 count면 모두 같은 자료형이에요'], '구조체의 저장 칸은 unsigned int, 함수 안 임시 칸은 int입니다. 뺄셈 결과를 다른 자료형에 넣는 단계까지 봐야 해요. 이름이 같다고 선언까지 같은 것은 아닙니다.')]), 'os1528': ('가위를 지금 빌릴 수 있으면 기다릴 시간이 없어도 바로 빌릴 수 있습니다. 가위가 없고 기다릴 시간도 끝났다면 실패입니다. 이 함수는 남은 시간 대신 빌렸는지를 알려 줍니다.', 'down_timeout의 0 성공·-ETIME 만료와 허가 우선 검사를 이해합니다.', 'count=1·timeout=0 → count=0·결과 0, count=0·timeout=0 → 결과 -ETIME의 두 경우를 비교하세요.', ['down_timeout은 제한된 시간 안에 세마포어 허가를 얻는 함수입니다. timeout은 long 형식의 시간 인자이며 단위는 jiffies, 즉 커널 시간 눈금입니다. 숫자를 초나 밀리초와 바로 같다고 생각하지 않습니다.', '반환형은 int이고 결과 0은 허가 획득 성공입니다. 허가 없이 시간이 끝나면 -ETIME을 돌려줍니다. 앞서 본 completion timeout의 0 만료·양수 성공과 다른 약속입니다. 이름의 timeout만으로 결과를 해석하지 마세요.', '바깥 함수는 잠금을 잡고 count > 0을 먼저 봅니다. 허가가 남았으면 하나 줄이고 성공 0으로 끝납니다. 이 길에서는 timeout을 검사하는 느린 경로에 들어가지 않습니다. 따라서 timeout=0이어도 준비된 허가를 얻을 수 있습니다.', '허가가 없으면 __down_timeout이 TASK_UNINTERRUPTIBLE 상태와 지정 시간을 공통 대기로 전달합니다. 공통 코드는 대기 항목을 등록하고 timeout <= 0인지 확인합니다. 시간이 끝났으면 항목을 빼고 -ETIME으로 나갑니다.', '시간이 남으면 잠금을 풀고 schedule_timeout으로 기다렸다가 다시 잡습니다. 허가를 직접 넘겨받았음을 나타내는 waiter.up이 참이면 성공 0입니다. 남은 시간이 몇 눈금인지 성공 결과로 돌려주는 함수는 아닙니다.', '실패 결과를 확인했다면 자원을 얻은 것처럼 사용하지 않습니다. timeout=0이라고 호출 문맥 조건도 사라지는 것은 아닙니다. 잠들 수 없는 상황에서의 즉시 시도가 필요하면 down_trylock의 별도 약속을 확인하세요. 성공 숫자와 대기 시간, 사용 상황을 각각 구별해야 합니다.'], [('down_timeout의 결과가 0이에요. 무슨 뜻인가요?', ['반드시 시간 만료예요', '허가를 얻었다는 성공이에요'], '이 함수는 성공 0, 시간 만료 -ETIME입니다. 남은 jiffies를 성공 값으로 돌려주는 다른 대기 함수의 규칙을 가져오면 0의 뜻을 반대로 읽게 됩니다.'), ('timeout=0이지만 count=1이에요. 성공할 수 있나요?', ['네. 먼저 허가를 하나 소비하고 성공해요', '아니요. 모든 경로에서 시간부터 검사해요'], '바깥 함수는 count가 양수인지 먼저 확인합니다. 1이면 하나 소비해 0으로 만들고 성공 결과 0을 반환해요. 허가가 없는 느린 경로에서 시간 검사가 이루어집니다.')])}
def run():
    additions={}
    for path in (ROOT/'course/lesson-parts').glob('*.json'):
        for lesson in json.loads(path.read_text(encoding='utf-8')):
            key=lesson['id']
            if key not in ROWS:continue
            practice=dict(lesson.get('practice',{}));practice['expected']=ROWS[key][2]
            additions[key]=dict(concepts=[],reading_support=None,deep_dive=[],goal=ROWS[key][1],experiment={'title':'종이에 따라 해 보기','steps':[ROWS[key][2]]},practice=practice)
    return rewrite(ROWS,'tools/rewrite_os_beginner_377.py',additions)
if __name__=='__main__':print(json.dumps(run(),ensure_ascii=False))
